<script setup lang="ts">
// A contact's portrait in the app's round `.avatar`. The portraits in
// /public/contacts were generated by the app's real portrait generator (see
// docs/site.md#example-portraits). `person` renders a human participant's
// initials instead, as the app does.
const props = withDefaults(defineProps<{ who?: CastId; person?: PersonId; size?: number; showcase?: boolean }>(), { size: 40, who: undefined, person: undefined });
const member = computed(() => (props.who ? cast[props.who] : undefined));
const { t } = useI18n();
const initials = computed(() => {
  if (!props.person) return '';
  return (props.person === 'you' ? t('cast.you') : people[props.person].name).slice(0, 1);
});
</script>

<template>
  <span v-if="person" class="avatar person" :style="{ width: `${size}px`, height: `${size}px`, fontSize: `${Math.round(size * 0.4)}px` }" aria-hidden="true">{{ initials }}</span>
  <span v-else-if="member" class="avatar" :style="{ width: `${size}px`, height: `${size}px` }" :title="member.name" aria-hidden="true">
    <img :src="showcase ? member.showcasePhoto : member.photo" alt="" :width="size" :height="size" decoding="async" draggable="false">
  </span>
</template>
